#!/usr/bin/env python3
"""Patch 35: every section as a card, with hover tilt and a following light. Frontend only.
Run from the repository root with patches 05-34 applied. Checked against the exact files it
was written for; nothing is written unless all of it matches. Safe to re-run."""
import hashlib, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
REPLACE = {'frontend/src/App.jsx': {'before': '6f5df0eec32ab3480a19f2e6790095090c2ea81b3dae126d4df5e091778b304a', 'after': 'import { Suspense, lazy, useCallback, useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport Overview from \'./Overview\';\nimport FamilyChips from \'./FamilyChips\';\nimport ConfidenceBadge from \'./ConfidenceBadge\';\nimport { attachStickyHeaders } from \'./stickyHeaders\';\nimport { attachTilt } from \'./tilt\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport RankingRevealCard from \'./cards/RankingRevealCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\n// loaded only when a tour starts, so driver.js is not in every page view\nconst Tour = lazy(() => import(\'./tour/Tour\'));\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  // Routes live in the URL hash, so Back and Forward work: #/overview (the\n  // default) or #/case/<id>. The last case opened stays loaded behind the\n  // overview, so returning to it is instant.\n  const parseRoute = () => {\n    const m = window.location.hash.match(/^#\\/case\\/([\\w-]+)/);\n    return m ? { view: \'case\', id: m[1] } : { view: \'overview\', id: null };\n  };\n  const [route, setRoute] = useState(parseRoute);\n  useEffect(() => {\n    const on = () => setRoute(parseRoute());\n    window.addEventListener(\'hashchange\', on);\n    return () => window.removeEventListener(\'hashchange\', on);\n  }, []);\n  const [lastCase, setLastCase] = useState(route.id ?? \'case_0001\');\n  if (route.id && route.id !== lastCase) setLastCase(route.id);\n  const incidentId = route.id ?? lastCase;\n  const openCase = useCallback((id) => { window.location.hash = `#/case/${id}`; }, []);\n  const openOverview = useCallback(() => { window.location.hash = \'#/overview\'; }, []);\n  // family filter for the overview grid; the sidebar always lists every case\n  const [family, setFamily] = useState(\'all\');\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n  // hover tilt and light for every card, one listener for the app\n  useEffect(() => attachTilt(), []);\n\n\n  const [touring, setTouring] = useState(false);\n\n  // Cross-fade between cases: the last fully loaded case stays on screen (dimmed)\n  // until the next has loaded, then fades in - rather than blanking and\n  // reloading. Updated during render, the standard pattern for derived state.\n  const [shown, setShown] = useState(null);\n  if (c && (shown?.c !== c || shown?.report !== report || shown?.tracks !== tracks)) {\n    setShown({ id: incidentId, c, report, tracks });\n  }\n  const vid = shown?.id;\n  const vc = shown?.c;\n  const leaving = !!shown && shown.id !== incidentId;\n  const meta = vc?.meta;\n\n  // scroll-edge effect on the pinned card headers; the column remounts per case\n  useEffect(() => attachStickyHeaders(document.querySelector(\'.finder-features\')), [vid, route.view]);\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && route.view === \'case\' && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          {route.view === \'case\' && vc && <ConfidenceBadge key={`conf-${vid}`} attribution={vc.attribution} />}\n          <button type="button" className={`tour-btn${touring ? \' is-on\' : \'\'}`} onClick={() => setTouring((t) => !t)}>\n            {touring ? \'Exit Tour\' : \'Start Tour\'}\n          </button>\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n      {touring && incidents.length > 0 && (\n        <Suspense fallback={null}>\n          <Tour incidents={incidents} api={api} selectCase={openCase} onExit={() => setTouring(false)} />\n        </Suspense>\n      )}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <button type="button" className={`nav-overview${route.view === \'overview\' ? \' is-active\' : \'\'}`} onClick={openOverview}>\n            <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 2h5v5H2zM9 2h5v5H9zM2 9h5v5H2zM9 9h5v5H9z" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" /></svg>\n            Overview\n          </button>\n          <CaseSwitcher incidents={incidents} active={route.view === \'case\' ? incidentId : null} onSelect={openCase} />\n        </aside>\n\n        {route.view === \'overview\' ? (\n          <Overview api={api} onOpen={openCase} family={family}\n                    chips={<FamilyChips incidents={incidents} value={family} onChange={setFamily} className="in-overview" />} />\n        ) : (\n        <div className={`finder-content${leaving ? \' is-leaving\' : \'\'}`} data-case={vid}>\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={vid}>\n            {vc && (\n              <>\n                <CaseFindingCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <RankingRevealCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <ObservedSceneCard meta={meta} slick={vc.slick} sceneUrl={api.sceneUrl(vid)}\n                                   nVessels={vc.vessels.length} />\n                <HistoricalReplayCard incidentId={vid} api={api} c={vc} tracks={shown.tracks} />\n                <FragilityCard fragility={vc.fragility} attribution={vc.attribution} />\n                <ForecastCard forecast={vc.forecast} />\n                <CoverageCard coverage={vc.coverage} />\n                <ProvenanceCard meta={meta} report={shown.report} />\n                {/* the case closes on what to check next */}\n                <NextObservationCard nextObs={vc.next_observation} closing />\n              </>\n            )}\n          </div>\n\n          <div className="finder-details" key={`d-${vid}`}>\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(vid)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(vid)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            {vc && (\n              <ConclusionGraph key={vid} attribution={vc.attribution} naive={vc.baseline}\n                               report={shown.report} detection={vc.slick} fragility={vc.fragility} />\n            )}\n            {vid && <AskSlickTraceCard key={`ask-${vid}`} incidentId={vid} api={api} />}\n          </div>\n        </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'}, 'frontend/src/overview.css': {'before': '0150ed25809fc5848a54ebba51cf62ac3bb9a875fded350b98cb12a9c9159c70', 'after': '/* Mission control: every case as a glass tile. */\n.ov { flex: 1; min-width: 0; height: 100%; overflow-y: auto; padding: var(--space-7) var(--space-7) var(--space-8); }\n.ov-head h1 { font-family: var(--font-display); font-size: 26px; font-weight: 700; letter-spacing: -0.02em; color: var(--label-1); }\n.ov-head p { margin: 4px 0 var(--space-6); font-size: var(--font-size-sm); color: var(--label-2); }\n.ov-loading { color: var(--label-2); font-size: var(--font-size-sm); }\n.ov-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)); gap: 16px; }\n.ov-tile {\n  position: relative; display: flex; flex-direction: column; gap: 10px; min-height: 176px; padding: 16px 16px 14px;\n  border: 0; border-radius: 14px; text-align: left; font: inherit; color: var(--label-1); cursor: default;\n  background: linear-gradient(160deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.015)), var(--surface-raised);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 6px 20px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.06);\n  --lift: 0px;\n  transform: perspective(900px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg)) translateY(var(--lift));\n  animation: ov-in 480ms var(--ease-spring) backwards; animation-delay: calc(var(--k) * 45ms);\n  transition: transform 700ms cubic-bezier(0.22, 1.2, 0.36, 1), box-shadow var(--dur-base) ease;\n}\n.ov-tile.is-tilting { transition: transform 160ms ease-out, box-shadow var(--dur-base) ease; }\n.ov-tile::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; opacity: 0;\n                  background: radial-gradient(360px circle at var(--mx, 50%) var(--my, 0%), rgba(var(--sheen-rgb), var(--sheen-max)), transparent 50%);\n                  transition: opacity 300ms ease; }\n.ov-tile.is-tilting::after { opacity: 1; }\n.ov-tile:hover { --lift: -3px; box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.55), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(10, 132, 255, 0.12); }\n.ov-tile:active { --lift: 1px; }\n.ov-tile:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 2px; }\n.ov-tile.is-abstain { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.55), 0 6px 20px rgba(0, 0, 0, 0.12); }\n.ov-tile.is-abstain:hover { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.8), 0 14px 32px rgba(0, 0, 0, 0.2), 0 0 24px rgba(255, 159, 10, 0.14); }\n.ov-top { display: flex; align-items: center; gap: 8px; }\n.ov-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--label-3); flex: none; }\n.ov-dot.is-named { background: var(--status-green); box-shadow: 0 0 8px rgba(48, 209, 88, 0.6); }\n.ov-dot.is-abstain { background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.6); }\n.ov-id { font-family: var(--font-mono); font-size: var(--font-size-sm); font-weight: var(--font-weight-semibold); }\n.ov-family { margin-left: auto; padding: 2px 8px; border-radius: 999px; font-size: var(--font-size-xxs); color: var(--label-2);\n             background: var(--fill-pressed); white-space: nowrap; }\n.ov-finding { font-size: var(--font-size-sm); line-height: 1.45; color: var(--label-1); }\n.ov-finding.is-pending { color: var(--label-3); }\n.ov-facts { font-size: var(--font-size-xs); color: var(--label-2); }\n.ov-facts b { color: var(--label-1); font-weight: var(--font-weight-semibold); }\n.ov-facts .mono, .ov-facts b.mono { font-family: var(--font-mono); }\n.ov-open { margin-top: auto; font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); color: var(--accent);\n           opacity: 0; transform: translateX(-4px); transition: opacity var(--dur-base) ease, transform var(--dur-base) var(--ease-spring); }\n.ov-tile:hover .ov-open, .ov-tile:focus-visible .ov-open { opacity: 1; transform: none; }\n.ov-foot { margin-top: var(--space-6); font-size: var(--font-size-xs); color: var(--label-3); }\n@keyframes ov-in { from { opacity: 0; translate: 0 10px; } }\n@media (prefers-reduced-motion: reduce) { .ov-tile { animation: none; transform: none; } }\n\n/* the sidebar\'s way back to the overview */\n.nav-overview { display: flex; align-items: center; gap: 9px; width: 100%; margin: 0 0 10px; padding: 8px 12px;\n                border: 0; border-radius: 9px; background: transparent; color: var(--label-1); font: inherit;\n                font-size: var(--font-size-sm); font-weight: var(--font-weight-medium); cursor: default; text-align: left; }\n.nav-overview:hover { background: var(--fill-hover); }\n.nav-overview.is-active { background: var(--accent); color: var(--on-accent); }\n.nav-overview svg { width: 15px; height: 15px; flex: none; }\n'}, 'frontend/src/shell.css': {'before': 'a851bb6fe193cdf91e7df927eb07cb77d257152e9a0a4be63c281a34152eee2e', 'after': '/*\n * App shell, in the manner of a native macOS window: a unified translucent\n * toolbar, a vibrant source-list sidebar with one selection that slides\n * between rows, a content column of sections divided by hairlines rather than\n * boxed cards, and a translucent inspector.\n *\n * Tokens come from index.css. Nothing here is case-specific: panels keep\n * their own internal styles in dashboard.css and inherit the theme through\n * the aliased legacy variables.\n */\n\n/* ----------------------------------------------------------------- window */\n\n.app-shell {\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  background: var(--window-bg);\n}\n\n.finder-layout {\n  display: flex;\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.finder-content {\n  flex: 1;\n  display: flex;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n}\n\n/* ---------------------------------------------------------------- toolbar */\n\n.topbar {\n  position: relative;\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  gap: var(--space-4);\n  height: 52px;\n  padding: 0 var(--space-4) 0 var(--space-5);\n  flex-shrink: 0;\n  background: var(--material-bar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-bottom: 1px solid var(--separator);\n}\n\n.wordmark {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  min-width: 0;\n  white-space: nowrap;\n  font-family: var(--font-body);\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: -0.003em;\n  color: var(--label-1);\n}\n\n.wordmark-mark {\n  width: 18px;\n  height: 18px;\n  flex: 0 0 auto;\n  border-radius: 5px;\n}\n\n.wordmark-sub {\n  font-weight: var(--font-weight-normal);\n  color: var(--label-2);\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.topbar-trailing {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  margin-left: auto;\n}\n\n.topbar-meta {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n/* ---------------------------------------------------------------- badges */\n\n.tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 20px;\n  padding: 0 var(--space-2);\n  border: 0;\n  border-radius: 999px;\n  background: var(--fill-hover);\n  color: var(--label-2);\n  font-family: var(--font-body);\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-medium);\n  letter-spacing: 0.005em;\n  line-height: 1;\n  text-transform: none;\n  white-space: nowrap;\n}\n\n.tag-teal,\n.tag-amber,\n.tag-green,\n.tag-red {\n  font-variant-caps: normal;\n}\n\n.tag-teal::before,\n.tag-amber::before,\n.tag-green::before,\n.tag-red::before {\n  content: "";\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: currentColor;\n}\n\n.tag-teal  { color: var(--accent);        background: var(--accent-soft); }\n.tag-amber { color: var(--status-orange); background: var(--status-orange-soft); }\n.tag-green { color: var(--status-green);  background: var(--status-green-soft); }\n.tag-red   { color: var(--status-red);    background: var(--status-red-soft); }\n\n/* ---------------------------------------------------------------- sidebar */\n\n.finder-sidebar {\n  width: 264px;\n  min-width: 264px;\n  flex-shrink: 0;\n  overflow-y: auto;\n  padding: var(--space-3) 10px var(--space-4);\n  background: var(--material-sidebar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-right: 1px solid var(--separator);\n}\n\n.case-switcher {\n  display: flex;\n  flex-direction: column;\n}\n\n.case-switcher-label {\n  display: block;\n  padding: 6px 10px 6px;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: 0.01em;\n  color: var(--label-3);\n}\n\n.case-list-wrap {\n  position: relative;\n}\n\n.case-list {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* One selection that travels between rows instead of colours swapping. */\n.case-highlight {\n  position: absolute;\n  z-index: 0;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: var(--h, 0px);\n  transform: translateY(var(--y, 0px));\n  border-radius: 7px;\n  background: var(--accent);\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14), inset 0 0.5px 0 rgba(255, 255, 255, 0.22);\n  opacity: 0;\n  pointer-events: none;\n}\n\n.case-highlight.is-ready {\n  opacity: 1;\n  transition: transform var(--dur-base) var(--ease-spring),\n              height var(--dur-base) var(--ease-spring),\n              opacity var(--dur-fast) ease;\n}\n\n.case-item {\n  position: relative;\n  width: 100%;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 7px 10px;\n  border: 0;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--label-1);\n  font: inherit;\n  text-align: left;\n  cursor: default;\n  transition: background-color var(--dur-fast) ease,\n              color var(--dur-base) var(--ease-out),\n              transform var(--dur-base) var(--ease-spring);\n}\n\n.case-item:hover:not(.is-active) {\n  background: var(--fill-hover);\n}\n\n.case-item:active {\n  transform: scale(0.98);\n  transition-duration: var(--dur-fast), var(--dur-fast), var(--dur-fast);\n}\n\n.case-item.is-active {\n  color: var(--on-accent);\n}\n\n.case-item:focus-visible {\n  outline: 3px solid var(--accent-ring);\n  outline-offset: 0;\n}\n\n.case-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  line-height: 1.25;\n}\n\n.case-id {\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-medium);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.case-description {\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  transition: color var(--dur-base) var(--ease-out);\n}\n\n.case-item.is-active .case-description {\n  color: rgba(255, 255, 255, 0.8);\n}\n\n.case-indicator {\n  flex: 0 0 auto;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  box-shadow: inset 0 0 0 0.5px rgba(0, 0, 0, 0.12);\n  transition: background-color var(--dur-base) var(--ease-out);\n}\n\n.indicator-known   { background: var(--status-green); }\n.indicator-unknown { background: var(--status-orange); }\n\n.case-item.is-active .indicator-known,\n.case-item.is-active .indicator-unknown {\n  background: var(--on-accent);\n}\n\n/* ---------------------------------------------------------------- content */\n\n.finder-features {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: 0 var(--space-7) var(--space-8);\n  background: var(--content-bg);\n}\n\n.finder-features > * {\n  width: 100%;\n  max-width: 1040px;\n  margin-inline: auto;\n}\n\n/* Sections, not cards: no border, fill or shadow; hairlines between them. */\n.panel {\n  flex-shrink: 0;\n  padding: var(--space-6) 0;\n  border: 0;\n  border-top: 1px solid var(--separator);\n  border-radius: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  box-shadow: none;\n}\n\n.panel-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: var(--space-2) var(--space-3);\n  margin-bottom: 14px;\n}\n\n.panel-head h2 {\n  font-family: var(--font-display);\n  font-size: var(--font-size-md);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: -0.012em;\n  color: var(--label-1);\n}\n\n/* Section titles pin while their section scrolls beneath - with a scroll-edge\n   effect, not a translucent material. At rest the header is clear. While its\n   card\'s content passes under it (is-stuck, set by stickyHeaders.js) it takes\n   the pane\'s own solid background, a hairline, and a soft fade below, so\n   content dissolves under it instead of being smeared into a blurred band. */\n.finder-features .panel > .panel-head {\n  position: sticky;\n  top: 0;\n  z-index: 3;\n  margin: calc(-1 * var(--space-6)) calc(-1 * var(--space-3)) 14px;\n  padding: var(--space-3) var(--space-3) var(--space-2);\n  background: transparent;\n  transition: background-color 160ms ease, box-shadow 160ms ease;\n}\n.finder-features .panel > .panel-head::after {\n  content: ""; position: absolute; left: 0; right: 0; top: 100%; height: 18px; pointer-events: none;\n  background: linear-gradient(to bottom, var(--content-bg), color-mix(in srgb, var(--content-bg) 0%, transparent));\n  opacity: 0; transition: opacity 160ms ease;\n}\n.finder-features .panel > .panel-head.is-stuck {\n  background: var(--content-bg);\n  box-shadow: 0 0.5px 0 var(--separator);\n}\n.finder-features .panel > .panel-head.is-stuck::after { opacity: 1; }\n\n.finder-features .panel {\n  padding-top: var(--space-6);\n}\n\n.finder-features > .verdict {\n  margin-top: var(--space-6);\n  margin-bottom: var(--space-6);\n}\n\n/* -------------------------------------------------------------- inspector */\n\n.finder-details {\n  width: 340px;\n  min-width: 340px;\n  flex-shrink: 0;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  padding: var(--space-5);\n  background: var(--material-sidebar);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  border-left: 1px solid var(--separator);\n}\n\n.finder-details .panel {\n  padding: 0;\n  border-top: 0;\n}\n\n.finder-details .console-panel {\n  flex: 1;\n  min-height: 320px;\n  padding: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  border-radius: 0;\n}\n\n.report-buttons {\n  display: flex;\n  gap: var(--space-2);\n  margin-bottom: var(--space-5);\n}\n\n/* ---------------------------------------------------------------- buttons */\n\n.report-button {\n  flex: 1;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 28px;\n  padding: 0 var(--space-3);\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  color: var(--label-1);\n  box-shadow: var(--shadow-control);\n  font-size: var(--font-size-base);\n  font-weight: var(--font-weight-medium);\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: default;\n  transition: transform var(--dur-base) var(--ease-spring),\n              background-color var(--dur-fast) ease;\n}\n\n.report-button:hover {\n  background: var(--control-bg-hover);\n}\n\n.report-button:active {\n  transform: scale(0.97);\n  background: var(--control-bg-pressed);\n  transition-duration: var(--dur-fast);\n}\n\n/* Panel controls: same springs, no lifts, no colour flashes. */\n.suggestion,\n.frag-step,\n.console-input-row button,\n.probe-close,\n.metric-info-trigger {\n  transition: transform var(--dur-base) var(--ease-spring),\n              background-color var(--dur-fast) ease,\n              border-color var(--dur-fast) ease,\n              color var(--dur-fast) ease;\n}\n\n.suggestion {\n  border: 0;\n  border-radius: var(--radius-md);\n  background: var(--surface-sunken);\n  padding: 9px 12px;\n  font-size: var(--font-size-sm);\n  color: var(--label-1);\n  cursor: default;\n}\n\n.suggestion:hover {\n  background: var(--fill-pressed);\n  box-shadow: none;\n  transform: none;\n}\n\n.frag-step {\n  border-radius: var(--radius-sm);\n  background: var(--surface-raised);\n  cursor: default;\n}\n\n.frag-step:hover {\n  background: var(--fill-hover);\n  transform: none;\n}\n\n.console-input-row {\n  border-top: 1px solid var(--separator);\n  padding-top: var(--space-3);\n  margin-top: var(--space-2);\n}\n\n.console-input-row input {\n  height: 28px;\n  padding: 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  font-size: var(--font-size-sm);\n  transition: box-shadow var(--dur-fast) ease;\n}\n\n.console-input-row input:focus {\n  outline: none;\n  box-shadow: var(--shadow-control), 0 0 0 3px var(--accent-ring);\n}\n\n.console-input-row button {\n  height: 28px;\n  padding: 0 14px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--accent);\n  color: var(--on-accent);\n  box-shadow: 0 1px 1.5px rgba(0, 0, 0, 0.12), inset 0 0.5px 0 rgba(255, 255, 255, 0.2);\n  cursor: default;\n}\n\n.console-input-row button:hover {\n  background: var(--accent-hover);\n  box-shadow: 0 1px 1.5px rgba(0, 0, 0, 0.12), inset 0 0.5px 0 rgba(255, 255, 255, 0.2);\n  transform: none;\n}\n\n.suggestion:active,\n.frag-step:active,\n.console-input-row button:active:not(:disabled),\n.probe-close:active,\n.metric-info-trigger:active {\n  transform: scale(0.96);\n  transition-duration: var(--dur-fast);\n}\n\n/* ------------------------------------------------------------- popovers */\n\n.metric-info-popover {\n  border: 0;\n  border-radius: var(--radius-lg);\n  background: var(--elevated-bg);\n  box-shadow: var(--shadow-float);\n  padding: 10px 12px;\n  animation: popover-in var(--dur-base) var(--ease-spring);\n}\n\n@keyframes popover-in {\n  from { opacity: 0; transform: translateY(-3px) scale(0.98); }\n  to   { opacity: 1; transform: none; }\n}\n\n/* ---------------------------------------------------------- theme control */\n\n.theme-toggle {\n  position: relative;\n  display: inline-grid;\n  grid-auto-flow: column;\n  grid-auto-columns: 30px;\n  height: 24px;\n  padding: 2px;\n  border-radius: 7px;\n  background: var(--fill-hover);\n  box-shadow: inset 0 0 0 0.5px var(--separator);\n}\n\n.theme-toggle-thumb {\n  position: absolute;\n  top: 2px;\n  bottom: 2px;\n  left: 2px;\n  width: 30px;\n  border-radius: 5px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  transform: translateX(calc(var(--i, 0) * 30px));\n  transition: transform var(--dur-base) var(--ease-spring);\n  pointer-events: none;\n}\n\n.theme-seg {\n  position: relative;\n  z-index: 1;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 5px;\n  background: transparent;\n  color: var(--label-2);\n  cursor: default;\n  transition: color var(--dur-fast) ease, transform var(--dur-base) var(--ease-spring);\n}\n\n.theme-seg:hover {\n  color: var(--label-1);\n}\n\n.theme-seg:active {\n  transform: scale(0.92);\n  transition-duration: var(--dur-fast);\n}\n\n.theme-seg[aria-checked="true"] {\n  color: var(--label-1);\n}\n\n.theme-seg svg {\n  width: 14px;\n  height: 14px;\n}\n\n/* ----------------------------------------------------------------- notices */\n\n.error-banner {\n  flex-shrink: 0;\n  margin: var(--space-3) var(--space-5) 0;\n  padding: 10px 14px;\n  border: 0;\n  border-radius: var(--radius-lg);\n  background: var(--status-red-soft);\n  color: var(--status-red);\n  font-size: var(--font-size-sm);\n}\n\n/* -------------------------------------------- materials without vibrancy */\n\n@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n  .topbar { background: var(--solid-bar); }\n  .finder-sidebar, .finder-details { background: var(--solid-sidebar); }\n}\n\n@media (prefers-reduced-transparency: reduce) {\n  .topbar { background: var(--solid-bar); backdrop-filter: none; -webkit-backdrop-filter: none; }\n  .finder-sidebar, .finder-details {\n    background: var(--solid-sidebar); backdrop-filter: none; -webkit-backdrop-filter: none;\n  }\n  .finder-features .panel > .panel-head, .finder-features .panel > .panel-head::after { transition: none; }\n}\n\n/* ------------------------------------------------------------- narrow widths */\n\n/* Stacked: one scroll container for the whole page, so the columns flow one\n   after another instead of each clipping its own content. */\n@media (max-width: 1100px) {\n  .finder-layout {\n    flex-direction: column;\n    overflow-y: auto;\n  }\n  .finder-content {\n    flex: none;\n    flex-direction: column;\n    overflow: visible;\n  }\n  .finder-sidebar {\n    flex: none;\n    width: 100%;\n    min-width: 0;\n    max-height: 220px;\n    border-right: 0;\n    border-bottom: 1px solid var(--separator);\n  }\n  .finder-features {\n    flex: none;\n    min-height: auto;\n    overflow: visible;\n    padding: 0 var(--space-5) var(--space-6);\n  }\n  .finder-details {\n    flex: none;\n    width: 100%;\n    min-width: 0;\n    min-height: auto;\n    overflow: visible;\n    border-left: 0;\n    border-top: 1px solid var(--separator);\n  }\n  .console-panel { height: 420px; }\n}\n\n@media (max-width: 620px) {\n  .topbar { height: auto; flex-wrap: wrap; padding: 10px 14px; }\n  .topbar-trailing { width: 100%; justify-content: space-between; margin-left: 0; }\n  .wordmark-sub { display: none; }\n}\n\n/* the always-visible tour control, and the case cross-fade */\n.tour-btn {\n  height: 28px; padding: 0 12px; border: 0; border-radius: 7px; cursor: default;\n  background: var(--control-bg); color: var(--label-1); box-shadow: var(--shadow-control);\n  font: inherit; font-size: var(--font-size-sm); font-weight: var(--font-weight-medium);\n}\n.tour-btn:hover { background: var(--control-bg-hover); }\n.tour-btn.is-on { background: var(--accent); color: var(--on-accent); }\n.finder-content { transition: opacity 150ms ease; }\n.finder-content.is-leaving { opacity: 0.25; }\n.finder-content > .finder-features, .finder-content > .finder-details { animation: st-case-in 180ms ease; }\n@keyframes st-case-in { from { opacity: 0; } }\n\n@media (prefers-reduced-motion: reduce) {\n  .finder-content > .finder-features, .finder-content > .finder-details { animation: none; }\n}\n\n/* ================================================================== cards */\n/* Every section is a card on a soft pane: its own surface, a hairline edge and\n   a soft shadow, leaning away from the pointer (tilt.js) with a light that\n   follows it. Sticky headers keep their scroll-edge effect, in the card\'s colour. */\n:root { --pane-bg: #f2f2f5; --card-bg: #ffffff; --sheen-rgb: 10, 132, 255; --sheen-max: 0.06; }\n:root[data-theme="dark"] { --pane-bg: #19191b; --card-bg: #232326; --sheen-rgb: 255, 255, 255; --sheen-max: 0.07; }\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) { --pane-bg: #19191b; --card-bg: #232326; --sheen-rgb: 255, 255, 255; --sheen-max: 0.07; }\n}\n@property --sheen { syntax: "<number>"; inherits: false; initial-value: 0; }\n\n.finder-features {\n  background:\n    radial-gradient(900px 500px at 12% -10%, rgba(10, 132, 255, 0.07), transparent 60%),\n    radial-gradient(800px 600px at 110% 20%, rgba(90, 200, 250, 0.05), transparent 60%),\n    var(--pane-bg);\n}\n.finder-features > .panel,\n.finder-details > .cg,\n.finder-details > .panel {\n  position: relative;\n  margin-top: var(--space-5);\n  padding: var(--space-5) var(--space-6) var(--space-6);\n  border: 0;\n  border-radius: 18px;\n  background:\n    radial-gradient(560px circle at var(--mx, 50%) var(--my, 0%), rgba(var(--sheen-rgb), calc(var(--sheen) * var(--sheen-max))), transparent 45%),\n    var(--card-bg);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 1px 2px rgba(0, 0, 0, 0.05), 0 10px 30px rgba(0, 0, 0, 0.07);\n  transform: perspective(1400px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));\n  transition: transform 700ms cubic-bezier(0.22, 1.2, 0.36, 1), box-shadow 300ms ease, --sheen 400ms ease;\n  animation: card-in 520ms cubic-bezier(0.22, 1.2, 0.36, 1) backwards;\n}\n.finder-features > .panel:first-child { margin-top: var(--space-6); }\n.finder-features > .panel.is-tilting,\n.finder-details > .cg.is-tilting,\n.finder-details > .panel.is-tilting {\n  --sheen: 1;\n  transition: transform 160ms ease-out, box-shadow 300ms ease, --sheen 300ms ease;\n  box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.45), 0 2px 4px rgba(0, 0, 0, 0.06), 0 18px 44px rgba(0, 0, 0, 0.12);\n}\n/* the entrance: a separate property from the tilt\'s transform, so they never fight */\n@keyframes card-in { from { opacity: 0; translate: 0 12px; } }\n.finder-features > .panel:nth-child(2) { animation-delay: 40ms; }\n.finder-features > .panel:nth-child(3) { animation-delay: 80ms; }\n.finder-features > .panel:nth-child(4) { animation-delay: 120ms; }\n.finder-features > .panel:nth-child(5) { animation-delay: 160ms; }\n.finder-features > .panel:nth-child(n+6) { animation-delay: 200ms; }\n\n/* sticky headers inside a card: fill the card\'s width and top corners when stuck */\n.finder-features > .panel > .panel-head {\n  margin: calc(-1 * var(--space-5)) calc(-1 * var(--space-6)) 14px;\n  padding: var(--space-4) var(--space-6) var(--space-3);\n  border-radius: 18px 18px 0 0;\n}\n.finder-features > .panel > .panel-head.is-stuck { background: var(--card-bg); }\n.finder-features > .panel > .panel-head::after { background: linear-gradient(to bottom, var(--card-bg), transparent); }\n.finder-features .panel { padding-top: var(--space-5); }\n\n/* sections that were boxes of their own, or separated by rules, are cards now */\n.finder-features > .panel.finding { margin-top: var(--space-6); }\n.finder-details > .cg { border-bottom: 0; margin-bottom: 0; padding: var(--space-4) var(--space-4) var(--space-4); }\n.finder-details > .panel { padding: var(--space-4); }\n.finder-details > .cg:first-of-type { margin-top: var(--space-4); }\n\n/* the jump-to ring now outlines every card evenly */\n.finder-features > .panel.cg-flash::after,\n.finder-details > .cg.cg-flash::after { inset: -6px; border-radius: 24px; }\n\n@media (prefers-reduced-motion: reduce) {\n  .finder-features > .panel, .finder-details > .cg, .finder-details > .panel { animation: none; transform: none; }\n}\n'}}
NEW = {'frontend/src/tilt.js': "/**\n * Hover tilt for every card: the side under the pointer leans away, and a soft\n * light follows it. One listener for the whole app, throttled to animation\n * frames, writing only CSS variables - no layout, no card logic.\n *\n * Tilt scales with size (small tiles lean more, large cards barely) so big\n * panels never swing. The Replay Map card does not rotate at all - a skewed map\n * would put clicks off target - but keeps the light. Off with reduced motion.\n */\nconst SELECTOR = '.finder-features > .panel, .finder-details > .cg, .finder-details > .panel, .ov-tile';\n\nexport function attachTilt() {\n  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return () => {};\n  let active = null, raf = 0, px = 0, py = 0;\n  const reset = (el) => {\n    el.classList.remove('is-tilting');\n    el.style.setProperty('--rx', '0deg');\n    el.style.setProperty('--ry', '0deg');\n  };\n  const apply = () => {\n    raf = 0;\n    if (!active || !active.isConnected) return;\n    const r = active.getBoundingClientRect();\n    const x = (px - r.left) / r.width, y = (py - r.top) / r.height;\n    const still = !!active.querySelector('.rmap');                 // the map card: light, no rotation\n    const max = still ? 0 : Math.min(10, 3600 / Math.max(r.width, r.height));\n    // the side under the pointer recedes (measured): pointer right -> positive rotateY\n    // pushes the right edge back; pointer at the top -> positive rotateX pushes the top back\n    active.style.setProperty('--ry', `${((x - 0.5) * max).toFixed(2)}deg`);\n    active.style.setProperty('--rx', `${((0.5 - y) * max).toFixed(2)}deg`);\n    active.style.setProperty('--mx', `${(x * 100).toFixed(1)}%`);\n    active.style.setProperty('--my', `${(y * 100).toFixed(1)}%`);\n    active.classList.add('is-tilting');\n  };\n  const onMove = (e) => {\n    const el = e.target.closest?.(SELECTOR) ?? null;\n    if (el !== active) { if (active) reset(active); active = el; }\n    if (!el) return;\n    px = e.clientX; py = e.clientY;\n    if (!raf) raf = requestAnimationFrame(apply);\n  };\n  const onLeave = () => { if (active) reset(active); active = null; };\n  document.addEventListener('pointermove', onMove, { passive: true });\n  document.addEventListener('pointerleave', onLeave);\n  window.addEventListener('blur', onLeave);\n  return () => {\n    cancelAnimationFrame(raf);\n    document.removeEventListener('pointermove', onMove);\n    document.removeEventListener('pointerleave', onLeave);\n    window.removeEventListener('blur', onLeave);\n  };\n}\n"}
CL_OLD = 'generator applies is not shown. Both have Layers toggles. 357 tests pass.\n'
CL_NEW = "generator applies is not shown. Both have Layers toggles. 357 tests pass.\n\n**Cards that respond.** Every section of a case, and of the inspector, is now a card on a soft\npane, with its own surface, hairline edge and shadow. Cards and overview tiles lean away on the\nside under the pointer - a little for large cards, more for small tiles - with a light that\nfollows it, and enter with a short stagger. The Replay Map card keeps the light but does not\nrotate, so clicks on the map stay on target. Sticky headers keep their scroll-edge effect in\nthe card's colour. Motion is off under reduced-motion settings.\n"
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text: skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 34 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 35: {len(writes)} files written, {skipped} already in place.")
